#include "pikapika/skinning_io.hpp"
#include <algorithm>
#include <cmath>
#include <functional>
#include <iostream>
#include <limits>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
namespace io=pikapika::skinning_io;
namespace sk=pikapika::skinning;
unsigned passed{};
void check(bool b,const char*s){if(!b)throw std::runtime_error(s);}
void near(double a,double b){check(std::abs(a-b)<1e-12,"Known geometric point");}
template<class F>void rejects(F f){bool caught=false;try{f();}catch(const std::exception&){caught=true;}check(caught,"Expected explicit rejection");}
void test(const char*name,const std::function<void()>&f){f();++passed;std::cout<<"PASS "<<name<<'\n';}
std::string save(const io::Source&s){std::ostringstream out;s.save(out);return out.str();}
io::Source load(const std::string&t){std::istringstream in(t);return io::Source::load(in);}
std::string changed(std::string s,std::string_view from,std::string_view to){const auto p=s.find(from);check(p!=std::string::npos,"Mutation anchor");s.replace(p,from.size(),to);return s;}
pikapika::Scene scene(const io::Source&s){pikapika::Scene out;pikapika::Entity e{42,"mesh","Context",{},0};e.mesh=s.mesh;out.entities.push_back(e);out.annotations={"# unrelated metadata retained"};return out;}
int main(){try{
    const auto base=io::example();const auto text=save(base);
    test("owned preset exact identity and independent FNV fingerprint",[&]{base.validate();check(base.target.native_id=="42"&&base.target.object_id=="arm-mesh"&&base.mesh.positions.size()==6&&base.joints.size()==2,"Preset domain");check(base.fingerprint=="9da65482c00e78b0","Independent JS FNV reference");check(base.rest_bones[0].id==19&&base.motion.bone_names[0]=="Child","Preset ordering");});
    test("portable roundtrip owns source and preserves canonical bytes",[&]{const auto s=load(text);check(save(s)==text,"Byte roundtrip");auto copy=s;copy.influences[0][0].weight=2;check(s.influences[0][0].weight==1,"Owned source copy");});
    test("existing motion FK and explicit inverse produce known six point deformation",[&]{const auto r=base.sample(1);check(r.status==sk::Status::completed&&r.positions&&r.positions->size()==6,"Sample completed");near((*r.positions)[2].x,1.2);near((*r.positions)[2].y,1);near((*r.positions)[0].x,0);near((*r.positions)[0].y,-.2);});
    test("clamp loop endpoint and absolute time do not mutate source",[&]{const auto a=base.sample(0),b=base.sample(2,pikapika::motion::Playback::loop),c=base.sample(100);check(a.positions&&b.positions&&c.positions,"Endpoint results");for(std::size_t j=0;j<6;++j){near((*a.positions)[j].x,(*b.positions)[j].x);near((*a.positions)[j].y,(*c.positions)[j].y);}check(save(base)==text,"Sampling source unchanged");rejects([&]{base.sample(-1);});});
    test("signed zero survives all outer numerical records and hash canonicalizes geometry zero",[&]{auto s=base;s.mesh.positions[0].z=-0.;s.influences[0].push_back({19,-0.});s.joints[0].rest_world[1]=-0.;s.joints[0].inverse_bind[3]=-0.;s.rest_bones[0].rest.position.y=-0.;check(io::mesh_fingerprint(s.mesh)==base.fingerprint,"Hash zero canonical");const auto back=load(save(s));check(std::signbit(back.mesh.positions[0].z)&&std::signbit(back.influences[0][1].weight)&&std::signbit(back.joints[0].rest_world[1])&&std::signbit(back.joints[0].inverse_bind[3])&&std::signbit(back.rest_bones[0].rest.position.y),"Outer signed zero retained");check(back.sample(1).positions.has_value(),"Zero equality in rest world");});
    test("names escapes Unicode and motion byte length roundtrip",[&]{auto s=base;s.name="Quote\" and slash\\";s.target.object_id="\xf0\x9f\xa4\x96 arm";s.motion.name="\xe3\x83\xad\xe3\x83\x9c";const auto back=load(save(s));check(back.name==s.name&&back.target.object_id==s.target.object_id&&back.motion.name==s.motion.name,"UTF-8 byte contract");});
    test("object Unicode bounds and canonical native IDs are strict",[&]{for(const auto&id:std::vector<std::string>{"0","01","+42","42.0","4.2e1","9007199254740992"}){auto s=base;s.target.native_id=id;rejects([&]{s.validate();});}auto s=base;s.target.native_id="9007199254740991";s.validate();s.target.object_id=std::string(96,'x');s.validate();s.target.object_id.push_back('x');rejects([&]{s.validate();});s.target.object_id="";rejects([&]{s.validate();});s.target.object_id=std::string("a\0b",3);rejects([&]{s.validate();});});
    test("non BMP object length counts UTF16 units not codepoints",[&]{auto s=base;s.target.object_id.clear();for(unsigned j=0;j<48;++j)s.target.object_id+="\xf0\x9f\xa4\x96";s.validate();s.target.object_id+="x";rejects([&]{s.validate();});});
    test("names invalid Unicode controls and byte excess reject",[&]{for(const auto&name:std::vector<std::string>{std::string(257,'x'),std::string("\xc0\x80",2),std::string("\xed\xa0\x80",3),std::string("\xf4\x90\x80\x80",4),std::string("\xe3\x80",2),"a\nb"}){auto s=base;s.name=name;rejects([&]{s.validate();});}});
    test("local rest snapshot rejects valid reparenting with exactly unchanged world matrix",[&]{auto m=base.motion;m.bones.push_back({11,7,{}});m.bone_names.push_back("Intermediate");auto s=io::create(base.name,base.target,base.mesh,m,base.influences);const auto before=s.motion.sample(0);s.motion.bones[0].parent_id=11;const auto after=s.motion.sample(0);check(before.pose&&after.pose&&before.pose->bones[0].world_matrix==after.pose->bones[0].world_matrix,"Reparenting world matrix is identical");rejects([&]{s.validate();});s=base;s.motion.bones[0].rest.position.x=2;rejects([&]{s.validate();});});
    test("bone order names and clip edits preserve immutable local snapshot",[&]{auto s=base;std::reverse(s.motion.bones.begin(),s.motion.bones.end());std::reverse(s.motion.bone_names.begin(),s.motion.bone_names.end());s.motion.name="Renamed";s.motion.bone_names[0]="Root renamed";s.motion.tracks[0].keys[1].pose.rotation={0,0,1,2};s.validate();check(s.sample(1).positions.has_value(),"Allowed motion edit");});
    test("stored rest world exact audit rejects epsilon mutation without inverse rebuilding",[&]{auto s=base;s.joints[0].rest_world[12]=std::nextafter(s.joints[0].rest_world[12],2.);s.validate();const auto t=save(s);rejects([&]{s.sample(1);});check(save(s)==t,"Rest mismatch did not repair original");});
    test("bad inverse is structurally preserved and numerical model failure is explicit",[&]{auto s=base;s.joints[0].inverse_bind[12]=99;s.validate();const auto back=load(save(s));check(back.joints[0].inverse_bind[12]==99,"No silent inverse rebuilding");const auto r=back.sample(1);check(r.status==sk::Status::ill_conditioned&&!r.positions,"Inverse model failure retained");});
    test("singular stored affine remains editable with explicit sample mismatch",[&]{auto s=base;s.joints[0].rest_world[0]=0;s.validate();const auto back=load(save(s));check(back.joints[0].rest_world[0]==0,"Singular preserved");rejects([&]{back.sample(1);});});
    test("positive weight underflow preserves author value and reports numerical failure",[&]{auto s=base;s.influences[1]={{19,std::numeric_limits<double>::denorm_min()},{7,std::numeric_limits<double>::max()}};const auto back=load(save(s));check(back.influences[1][0].weight==std::numeric_limits<double>::denorm_min(),"Positive author weight retained");const auto r=back.sample(1);check(r.status==sk::Status::numerical_failure&&!r.positions,"No discarded underflow influence");});
    test("weight edits use candidate validation and preserve source on failure",[&]{auto s=base;s.set_weight(1,7,3);check(s.influences[1][1].weight==3,"Known existing weight edit");const auto before=save(s);for(const auto f:std::vector<std::function<void()>>{[&]{s.set_weight(6,7,1);},[&]{s.set_weight(1,99,1);},[&]{s.set_weight(0,7,0);},[&]{s.set_weight(1,7,-1);},[&]{s.set_weight(1,7,std::numeric_limits<double>::quiet_NaN());}}){rejects(f);check(save(s)==before,"Failed edit unchanged");}});
    test("influence and joint ID sets must be unique exact and complete",[&]{auto s=base;s.influences[0].push_back({7,1});rejects([&]{s.validate();});s=base;s.influences[0].push_back({99,0});rejects([&]{s.validate();});s=base;s.joints[1].bone_id=19;rejects([&]{s.validate();});s=base;s.joints.pop_back();rejects([&]{s.validate();});s=base;s.rest_bones[0].id=7;rejects([&]{s.validate();});});
    test("matrix domain row and source geometry validity reject before output",[&]{for(double bad:{1e151,std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()}){auto s=base;s.joints[0].inverse_bind[0]=bad;rejects([&]{save(s);});}auto s=base;s.joints[0].inverse_bind[3]=1e-30;rejects([&]{s.validate();});s=base;s.mesh.triangles[0]={0,0,1};s.fingerprint="0000000000000000";rejects([&]{s.validate();});});
    test("mesh fingerprint detects ordered vertex topology and coordinate changes",[&]{auto s=base;s.mesh.positions[0].x=.01;rejects([&]{s.validate();});s=base;std::swap(s.mesh.triangles[0],s.mesh.triangles[1]);check(io::mesh_fingerprint(s.mesh)!=base.fingerprint,"Ordered topology hash");s=base;s.fingerprint="9DA65482c00e78b0";rejects([&]{s.validate();});});
    test("native context match uses numeric ID full geometry and ignores alias transform material",[&]{auto context=scene(base);context.entities[0].transform.position={10,20,30};context.entities[0].name="Different";auto s=base;s.target.object_id="declaration-only";s.match(context);auto before=std::ostringstream{};context.save(before);s.match(context);std::ostringstream after;context.save(after);check(before.str()==after.str(),"Match did not mutate scene");context.entities[0].mesh.positions[0].z=-0.;s.match(context);});
    test("native context rejects missing type reordered geometry and one ULP coordinate",[&]{auto c=scene(base);c.entities[0].id=43;rejects([&]{base.match(c);});c=scene(base);std::swap(c.entities[0].mesh.positions[0],c.entities[0].mesh.positions[1]);rejects([&]{base.match(c);});c=scene(base);c.entities[0].mesh.positions[1].x=std::nextafter(1.,2.);rejects([&]{base.match(c);});});
    test("portable nonzero decimal underflow and nonfinite literals reject",[&]{for(const auto&v:std::vector<std::string>{"1e-400","nan","inf","1e999"})rejects([&]{load(changed(text,"weights 1 7 1","weights 1 7 "+v));});});
    test("portable unknown fields escapes truncation and trailing data reject",[&]{for(const auto&t:std::vector<std::string>{changed(text,"space mesh-local-is-skeleton","space other"),changed(text,"name \"Original arm binding\"","name \"bad\\nname\""),changed(text,"object \"arm-mesh\" \"42\"","object \"arm-mesh\"\"42\""),text.substr(0,text.size()-10),text+"\n",text+"garbage",changed(text,"joints 2","joints 2 extra")})rejects([&]{load(t);});});
    test("portable motion byte count budget and UTF8 faults reject",[&]{const auto p=text.find("motion_bytes "),end=text.find('\n',p);const auto count=std::stoul(text.substr(p+13,end-p-13));for(auto size:{count-1,count+1,4194305UL})rejects([&]{load(changed(text,text.substr(p,end-p),"motion_bytes "+std::to_string(size)));});auto bad=text;bad.insert(bad.find("Original"),std::string("\xc0\xaf",2));rejects([&]{load(bad);});rejects([&]{load(std::string(8*1024*1024+1,' '));});});
    test("portable outer line and count limits reject before allocation",[&]{rejects([&]{load(changed(text,"name \"Original arm binding\"","name \""+std::string(4090,'a')+"\""));});for(const auto pair:{std::pair{"mesh 6 4","mesh 2049 4"},std::pair{"influences 6","influences 7"},std::pair{"weights 1 7 1","weights 5 7 1"},std::pair{"joints 2","joints 129"},std::pair{"rest_bones 2","rest_bones 129"}})rejects([&]{load(changed(text,pair.first,pair.second));});});
    test("failed loads and numerical calls do not poison next source",[&]{rejects([&]{load("bad");});const auto good=load(text);check(good.sample(.5).positions.has_value()&&save(good)==text,"Reuse after bad input");});
    test("2048 vertex 8192 influence boundary roundtrip and one over reject",[&]{auto mesh=base.mesh;mesh.positions.resize(2048,{0,0,0});auto m=base.motion;for(auto id:{11ULL,12ULL}){m.bones.push_back({id,7,{}});m.bone_names.push_back("Unused");}const std::vector<sk::Influence> weights{{7,1},{19,1},{11,1},{12,1}};auto s=io::create(base.name,base.target,mesh,m,std::vector<std::vector<sk::Influence>>(2048,weights));check(load(save(s)).sample(1).positions->size()==2048,"Maximum owned counts");s.mesh.positions.push_back({0,0,0});s.influences.push_back(weights);s.fingerprint=io::mesh_fingerprint(s.mesh);rejects([&]{s.validate();});});
    std::cout<<passed<<" skin binding IO groups passed\n";return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
